function verif1() {
    let nom = document.getElementById("nom").value;
    let prenom = document.getElementById("prenom").value;
    let tel = document.getElementById("tel").value;
    let adr = document.getElementById("adr").value;
    let psw = document.getElementById("psw").value;
    let psw2 = document.getElementById("psw2").value;

    if (nom.length < 3 || !alpha(nom)) {
        alert("nom invalide");
        return false;
    }
    if (prenom.length < 3 || !alpha(prenom)) {
        alert("prenom invalide");
        return false;
    }
    if(tel.length != 8 || isNaN(tel) || tel[0] == "1" || tel.charAt(0) == "0") {
        alert("tel invalide");
        return false;
    }
    if (adr.length < 10) {
        alert("adresse invalide");
        return false;
    }
    if (psw.length != 6 || psw.indexOf(" ") != -1) {
        alert("password invalide");
        return false;
    }
    if (psw2 != psw) {
        alert("confirmation invalide");
        return false;
    }
    return true
}

